 assert load_people(h+\"Sam,a@b,\"+age+\",1\")[0][\"age\"]==int(age.lstrip(\"0\") or \"0\"); n+=1
for active, expected in [(\"TRUE\",True),(\"1\",True),(\"false\",False),(\"0\",False),(\"\",False)]:
 assert load_people(h+\"Sam,a@b,0,\"+active)[0][\"active\"] is expected; n+=1
